package com.enis.sectio.project;
import com.enis.sectio.user.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import java.util.Optional;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class ProjectServiceTest{@Mock ProjectRepository projects;@Mock ProjectMemberRepository members;@Mock UserRepository users;ProjectService service;@BeforeEach void setup(){service=new ProjectService(projects,members,users);}
 @Test void ownerBecomesMemberWhenProjectIsCreated(){User admin=new User("Admin","admin@test.local","hash",Role.ADMIN);when(users.findByEmail("admin@test.local")).thenReturn(Optional.of(admin));when(projects.save(any())).thenAnswer(i->i.getArgument(0));service.create("admin@test.local","Project","Description");verify(members).save(argThat(m->m.getUser()==admin));}
 @Test void inactiveUserCannotBeAdded(){User admin=new User("Admin","admin@test.local","hash",Role.ADMIN);User inactive=new User("Inactive","inactive@test.local","hash",Role.EMPLOYEE);inactive.deactivate();Project p=new Project(admin,"Project",null);when(users.findByEmail("admin@test.local")).thenReturn(Optional.of(admin));when(projects.findById(1L)).thenReturn(Optional.of(p));when(users.findById(2L)).thenReturn(Optional.of(inactive));assertThatThrownBy(()->service.addMember(1L,2L,"admin@test.local")).isInstanceOf(ProjectException.class).hasMessageContaining("Inactive");}
}
